-- ---------------------------------------------------------------------
-- MIGRATION 19 - EVERY JUDGE GETS A COUNTY
-- ---------------------------------------------------------------------
-- Run after 18. Safe to run more than once. It is a large file (most of
-- it is the ZIP list in Part 1); paste the whole thing into the SQL
-- editor and run it in one go.
--
-- State directors group counties into regions (migration 18), and a
-- judge lands in a region by their county. Since migration 14 the judge
-- form asks for a ZIP code instead of a county, so new judges arrive with
-- no county at all and older ones have it mixed into the city field
-- ("Columbus, Franklin County").
--
-- This works the county out, in this order:
--   1. From the ZIP code, using the Census ZIP-to-county list below.
--   2. From "... X County" typed into the city field (older Ohio rows).
--   3. From the nearest ZIP in the same state with a known county, within
--      25 miles, if the judge has map coordinates. Needs us_zip_centroids
--      loaded (see migration 14); skipped quietly if it is empty.
-- A county someone already typed is kept, only tidied ("Franklin County"
-- becomes "Franklin", the form regions use). A trigger does the same for
-- every new or edited judge from now on.
--
-- Where the ZIP list comes from: the 2000 Census ZCTA-to-county table,
-- as republished at github.com/scpike/us-state-county-zip (US Census data
-- is public domain). 33,048 ZIP codes. ZIPs created since 2000 are not in
-- it - step 3 covers most of those. Connecticut is listed by its old
-- counties, which is still how most people there describe where they are.
--
-- Anything still without a county shows up on the state page as "has no
-- county", which is the list to fix by hand.


-- ---------------------------------------------------------------------
-- PART 1 - ZIP TO COUNTY
-- ---------------------------------------------------------------------

create table if not exists public.zip_counties (
  zip        char(5) primary key,
  state_code char(2) not null,
  county     text not null
);
create index if not exists zip_counties_state_idx on public.zip_counties (state_code, county);

alter table public.zip_counties enable row level security;
drop policy if exists "zip_counties_read" on public.zip_counties;
create policy "zip_counties_read" on public.zip_counties for select to anon, authenticated using (true);

comment on table public.zip_counties is
  'ZIP code to county, from the 2000 Census ZCTA relationship file. County names are bare ("Franklin", not "Franklin County").';

insert into public.zip_counties (zip, state_code, county)
select z, v.st, v.county
