-- us_zip_centroids has had an empty county column since migration 04.
update public.us_zip_centroids c
   set county = zc.county
  from public.zip_counties zc
 where zc.zip = c.zip and (c.county is null or c.county = '');


-- ---------------------------------------------------------------------
-- PART 2 - WORKING OUT ONE JUDGE'S COUNTY
-- ---------------------------------------------------------------------

create or replace function public.fg_county_for(
  p_state  text,
  p_postal text,
  p_city   text,
  p_lat    numeric,
  p_lng    numeric
)
returns text
language plpgsql
stable
set search_path = public
as $$
declare
  v_zip    text := substring(coalesce(p_postal, '') from '^\s*(\d{5})');
  v_county text;
begin
  if p_state is null then return null; end if;

  -- 1. ZIP code
  if v_zip is not null then
    select county into v_county from public.zip_counties
     where zip = v_zip and state_code = upper(p_state);
    if v_county is not null then return v_county; end if;
  end if;

  -- 2. "Columbus, Franklin County" in the city field
  v_county := public.fg_clean_county(substring(coalesce(p_city, '') from '([A-Za-z.'' -]+)\s+(?:County|Parish|Borough)\s*$'));
  if v_county is not null then
    select zc.county into v_county from public.zip_counties zc
     where zc.state_code = upper(p_state) and lower(zc.county) = lower(v_county)
     limit 1;
    if v_county is not null then return v_county; end if;
  end if;

  -- 3. Nearest ZIP with a known county, same state, within 25 miles
  if p_lat is not null and p_lng is not null then
    select zc.county into v_county
    from public.us_zip_centroids c
    join public.zip_counties zc on zc.zip = c.zip
    where zc.state_code = upper(p_state)
      and c.latitude  between p_lat - 0.4 and p_lat + 0.4
      and c.longitude between p_lng - 0.55 and p_lng + 0.55
      and sqrt(power(69.0 * (c.latitude - p_lat), 2)
             + power(69.0 * cos(radians(p_lat)) * (c.longitude - p_lng), 2)) <= 25
    order by power(c.latitude - p_lat, 2)
           + power(cos(radians(p_lat)) * (c.longitude - p_lng), 2)
    limit 1;
    if v_county is not null then return v_county; end if;
  end if;

  return null;
end;
$$;


-- ---------------------------------------------------------------------
-- PART 3 - EXISTING JUDGES
-- ---------------------------------------------------------------------

-- Tidy what is already there, so "Franklin County" and "Franklin" match.
update public.judges
   set county = public.fg_clean_county(county)
 where county is not null
   and county is distinct from public.fg_clean_county(county);

update public.judges j
   set county = public.fg_county_for(j.state_code, j.postal_code, j.city, j.latitude, j.longitude)
 where public.fg_clean_county(j.county) is null
   and coalesce(to_jsonb(j) ->> 'country', 'US') = 'US'
   and public.fg_county_for(j.state_code, j.postal_code, j.city, j.latitude, j.longitude) is not null;


-- ---------------------------------------------------------------------
-- PART 4 - NEW AND EDITED JUDGES
-- ---------------------------------------------------------------------
-- Fills county when it is blank, and refills it when the ZIP or state
-- changes and nobody also changed the county in the same edit.

create or replace function public.fg_judges_fill_county()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.county := public.fg_clean_county(new.county);
  if coalesce(to_jsonb(new) ->> 'country', 'US') <> 'US' then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.county is not distinct from public.fg_clean_county(old.county)
     and (new.postal_code is distinct from old.postal_code
          or new.state_code is distinct from old.state_code) then
    new.county := null;
  end if;
  if new.county is null then
    new.county := public.fg_county_for(new.state_code, new.postal_code, new.city,
                                       new.latitude, new.longitude);
  end if;
  return new;
end;
$$;

drop trigger if exists judges_fill_county on public.judges;
create trigger judges_fill_county
  before insert or update of county, postal_code, state_code, city, latitude, longitude
  on public.judges
  for each row execute function public.fg_judges_fill_county();


-- ---------------------------------------------------------------------
-- CHECK - how many judges have a county now, by state
-- ---------------------------------------------------------------------

select state_code,
       count(*)                                   as judges,
       count(*) filter (where county is not null) as with_county,
       count(*) filter (where county is null)     as still_missing
from public.judges
where coalesce(to_jsonb(judges) ->> 'country', 'US') = 'US'
group by state_code
order by still_missing desc, state_code;
